import React, {useState} from 'react';
import {Alert, Button, Dialog, DialogContent, DialogTitle, MenuItem, Stack, TextField, Typography} from '@mui/material';
import {TransportWaybillDto, TransportWaybillPartyRole, TransportWaybillProcessingStatus} from '../../models/transportWaybill';
import {getApiErrorMessage} from '../../api/errors';
import {companyIdentity, Counterparty, useApplyDocumentCounterpartyMutation} from './counterpartiesApi';
import CompanyPicker from './CompanyPicker';

export default function DocumentCounterparties({document, onSaved}: {document: TransportWaybillDto; onSaved: (version: string) => void}) {
    const [open, setOpen] = useState(false); const [role, setRole] = useState(TransportWaybillPartyRole.Shipper);
    const [partyId, setPartyId] = useState<number | ''>(''); const [error, setError] = useState('');
    const [apply, state] = useApplyDocumentCounterpartyMutation();
    const parties = (document.parties || []).filter(item => item.role === role);
    const party = parties.find(item => item.id === partyId) || parties[0];
    const editable = !!document.approvalVersion && !document.isArchived && !document.approvedReceiptId && document.status !== TransportWaybillProcessingStatus.Processing;
    async function save(company: Counterparty) {
        setError('');
        if (parties.length > 1 && !partyId) {setError('Выберите конкретного участника накладной.'); return;}
        try {const result = await apply({documentId: document.id, role, organization: companyIdentity(company), expectedVersion: document.approvalVersion!, partyId: party?.id}).unwrap(); setOpen(false); onSaved(result.approvalVersion);}
        catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось сохранить реквизиты.'));}
    }
    return <>
        <Button type="button" variant="outlined" onClick={() => setOpen(true)}>Проверить контрагентов в DaData</Button>
        <Dialog open={open} onClose={() => {if (!state.isLoading) setOpen(false);}} fullWidth maxWidth="md">
            <DialogTitle>Контрагенты накладной</DialogTitle><DialogContent><Stack spacing={2} sx={{pt: 1}}>
                <TextField select label="Роль в накладной" value={role} onChange={event => {setRole(Number(event.target.value)); setPartyId(''); setError('');}}>
                    {[[1,'Грузоотправитель'],[2,'Грузополучатель'],[3,'Перевозчик'],[4,'Заказчик'],[5,'Плательщик'],[100,'Другой участник']].map(([value, label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}
                </TextField>
                {parties.length > 1 && <TextField select label="Участник" value={partyId} onChange={event => setPartyId(Number(event.target.value))}><MenuItem value="">Выберите участника</MenuItem>{parties.map(item => <MenuItem key={item.id} value={item.id}>{item.name} · {item.unp}</MenuItem>)}</TextField>}
                <Typography variant="body2" color="text.secondary">{editable ? 'Выбранная организация заменит реквизиты этого участника. Сведения из реестра сохранятся вместе с накладной.' : 'Для этой накладной доступна проверка без изменения реквизитов.'}</Typography>
                {error && <Alert severity="error">{error}</Alert>}
                <CompanyPicker key={`${role}.${partyId}`} initialQuery={party?.unp || party?.name || ''} onSelect={editable && !state.isLoading ? company => void save(company) : undefined} selectLabel={state.isLoading ? 'Сохранение…' : 'Сохранить в накладной'}/>
                <Button disabled={state.isLoading} onClick={() => setOpen(false)}>Закрыть</Button>
            </Stack></DialogContent>
        </Dialog>
    </>;
}
